import java.util.*;

class Solution {
  public List<List<Integer>> findRLEArray(int[][] encoded1, int[][] encoded2) {
    List<List<Integer>> res = new ArrayList<>();
    int i = 0, j = 0, left1 = encoded1[0][1], left2 = encoded2[0][1];
    while (i < encoded1.length && j < encoded2.length) {
      int take = Math.min(left1, left2), product = encoded1[i][0] * encoded2[j][0];
      List<Integer> last = res.isEmpty() ? null : res.get(res.size() - 1);
      if (last != null && last.get(0) == product) last.set(1, last.get(1) + take);
      else res.add(new ArrayList<>(Arrays.asList(product, take)));
      left1 -= take;
      left2 -= take;
      if (left1 == 0 && ++i < encoded1.length) left1 = encoded1[i][1];
      if (left2 == 0 && ++j < encoded2.length) left2 = encoded2[j][1];
    }
    return res;
  }
}
